fn enc_options(out: &mut Vec<u8>, v: &Options, depth: i32) {
    out.push(b'{');
    let mut first = true;
    if v.max_output != 0 {
        first = false;
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "max_output");
        out.extend_from_slice(b": ");
        num(out, v.max_output);
    }
    if let Some(value) = &v.temperature {
        if !first {
            out.push(b',');
        }
        first = false;
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "temperature");
        out.extend_from_slice(b": ");
        enc_temperature(out, value, depth + 1);
    }
    if !v.stop.is_empty() {
        if !first {
            out.push(b',');
        }
        first = false;
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "stop");
        out.extend_from_slice(b": ");
        strs(out, &v.stop, depth + 1);
    }
    if !v.json_schema.is_empty() {
        if !first {
            out.push(b',');
        }
        first = false;
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "json_schema");
        out.extend_from_slice(b": ");
        esc(out, &v.json_schema);
    }
    if !first {
        out.push(b'\n');
        pad(out, depth);
    }
    out.push(b'}');
}

