/// Common generated framing boundary; implementation owns waiting and identity.
pub use abstraction_frame::FrameTransport;

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ServiceError {
    pub code: String,
    pub message: String,
}

#[derive(Debug)]
pub enum CallError<E> {
    /// Transport failure does not establish whether the receiver accepted work.
    Transport(E),
    Refusal(Refusal),
    Dispatch(&'static str),
    Service(ServiceError),
}

fn service_decode<T>(data: &[u8], decode: fn(&mut Reader) -> Result<T, Refusal>) -> Result<T, Refusal> {
    let mut r = Reader { buf: data, pos: 0, depth: 0 };
    r.skip_ws();
    let value = decode(&mut r)?;
    r.skip_ws();
    if r.pos != data.len() {
        return r.refuse("trailing_bytes");
    }
    Ok(value)
}

fn service_encode<T>(value: &T, check: fn(&T) -> Result<(), Refusal>, encode: fn(&mut Vec<u8>, &T, i32), decode: fn(&mut Reader) -> Result<T, Refusal>) -> Result<Vec<u8>, Refusal> {
    check(value)?;
    let mut data = Vec::new();
    encode(&mut data, value, 0);
    service_decode(&data, decode)?;
    Ok(data)
}

/// Model calls performed by the receiving runtime for the bound caller.
/// Operations are visible only to the account and program that started them.
/// Every request to a hosted host carries headers from abstraction.credentials
/// applier@1 applied for the bound caller, sent once and kept out of every
/// reply, delta, record and log. Caller exit cancels: an operation nobody
/// observes for idle_ms is closed, because a stream nobody reads is spend. A
/// decision point that cannot answer reads unavailable, never permission.
pub trait Chat {
    type Error;
    /// Admit one model call for the bound caller and begin it. In order:
    /// argument shape (invalid), guarantees and host selection through the
    /// router (no_host), host features and required extensions
    /// (unsupported_feature), the rights decision for
    /// abstraction.inference/complete on host:<name> (not_permitted, or
    /// unavailable when the decision point cannot answer), the credential's
    /// ceiling (budget_exceeded), the caller's concurrent operations
    /// (exhausted), then for a hosted host the credentials applier
    /// (not_permitted or unavailable). Nothing leaves the service before every
    /// check passes. Deltas are observed with Observe.
    fn start(&self, request: Request) -> Result<Admission, Self::Error>;
    /// Read a bounded page of an operation's deltas from cursor. max_deltas is
    /// 1..256, max_bytes 1..65536 and wait_ms 0..30000. When no delta at cursor
    /// exists yet and the operation has not ended, wait up to wait_ms for one,
    /// then return what is there. An Observe in flight keeps the operation from
    /// idling; a caller that disconnects mid-wait stops the wait. Reconnecting
    /// with the last next resumes without loss inside retained_deltas.
    fn observe(&self, operation: String, cursor: i64, max_deltas: i64, max_bytes: i64, wait_ms: i64) -> Result<DeltaPage, Self::Error>;
    /// Stop an operation the bound caller started and close its upstream
    /// request. Reports whether this call cancelled it or it had already ended.
    fn cancel(&self, operation: String) -> Result<Cancellation, Self::Error>;
}

pub struct ChatClient<T> {
    transport: T,
}

impl<T> ChatClient<T> {
    pub fn new(transport: T) -> Self {
        Self { transport }
    }

    pub fn transport(&self) -> &T {
        &self.transport
    }
}

impl<T: FrameTransport> Chat for ChatClient<T> {
    type Error = CallError<T::Error>;
    fn start(&self, request: Request) -> Result<Admission, Self::Error> {
        let args = OAChatStartArguments { request };
        let arguments = service_encode(&args, service_check_oa_chat_start_arguments, enc_oa_chat_start_arguments, decode_oa_chat_start_arguments).map_err(CallError::Refusal)?;
        let request = OAServiceFrame { version: 1, service: "abstraction.inference/chat@1".into(), method: "Start".into(), arguments };
        let frame = service_encode(&request, service_check_oa_service_frame, enc_oa_service_frame, decode_oa_service_frame).map_err(CallError::Refusal)?;
        let reply = self.transport.exchange_frame(&frame).map_err(CallError::Transport)?;
        let reply = service_decode(&reply, decode_oa_service_reply).map_err(CallError::Refusal)?;
        if reply.version != 1 {
            return Err(CallError::Dispatch("unknown_version"));
        }
        if reply.service != "abstraction.inference/chat@1" || reply.method != "Start" {
            return Err(CallError::Dispatch("mismatched_response"));
        }
        if !reply.ok {
            let error = service_decode(&reply.payload, decode_oa_service_error).map_err(CallError::Refusal)?;
            if error.code.is_empty() {
                return Err(CallError::Dispatch("invalid_error"));
            }
            return Err(CallError::Service(ServiceError { code: error.code, message: error.message }));
        }
        let result = service_decode(&reply.payload, decode_oa_chat_start_result).map_err(CallError::Refusal)?;
        Ok(result.value)
    }

    fn observe(&self, operation: String, cursor: i64, max_deltas: i64, max_bytes: i64, wait_ms: i64) -> Result<DeltaPage, Self::Error> {
        let args = OAChatObserveArguments { operation, cursor, max_deltas, max_bytes, wait_ms };
        let arguments = service_encode(&args, service_check_oa_chat_observe_arguments, enc_oa_chat_observe_arguments, decode_oa_chat_observe_arguments).map_err(CallError::Refusal)?;
        let request = OAServiceFrame { version: 1, service: "abstraction.inference/chat@1".into(), method: "Observe".into(), arguments };
        let frame = service_encode(&request, service_check_oa_service_frame, enc_oa_service_frame, decode_oa_service_frame).map_err(CallError::Refusal)?;
        let reply = self.transport.exchange_frame(&frame).map_err(CallError::Transport)?;
        let reply = service_decode(&reply, decode_oa_service_reply).map_err(CallError::Refusal)?;
        if reply.version != 1 {
            return Err(CallError::Dispatch("unknown_version"));
        }
        if reply.service != "abstraction.inference/chat@1" || reply.method != "Observe" {
            return Err(CallError::Dispatch("mismatched_response"));
        }
        if !reply.ok {
            let error = service_decode(&reply.payload, decode_oa_service_error).map_err(CallError::Refusal)?;
            if error.code.is_empty() {
                return Err(CallError::Dispatch("invalid_error"));
            }
            return Err(CallError::Service(ServiceError { code: error.code, message: error.message }));
        }
        let result = service_decode(&reply.payload, decode_oa_chat_observe_result).map_err(CallError::Refusal)?;
        Ok(result.value)
    }

    fn cancel(&self, operation: String) -> Result<Cancellation, Self::Error> {
        let args = OAChatCancelArguments { operation };
        let arguments = service_encode(&args, service_check_oa_chat_cancel_arguments, enc_oa_chat_cancel_arguments, decode_oa_chat_cancel_arguments).map_err(CallError::Refusal)?;
        let request = OAServiceFrame { version: 1, service: "abstraction.inference/chat@1".into(), method: "Cancel".into(), arguments };
        let frame = service_encode(&request, service_check_oa_service_frame, enc_oa_service_frame, decode_oa_service_frame).map_err(CallError::Refusal)?;
        let reply = self.transport.exchange_frame(&frame).map_err(CallError::Transport)?;
        let reply = service_decode(&reply, decode_oa_service_reply).map_err(CallError::Refusal)?;
        if reply.version != 1 {
            return Err(CallError::Dispatch("unknown_version"));
        }
        if reply.service != "abstraction.inference/chat@1" || reply.method != "Cancel" {
            return Err(CallError::Dispatch("mismatched_response"));
        }
        if !reply.ok {
            let error = service_decode(&reply.payload, decode_oa_service_error).map_err(CallError::Refusal)?;
            if error.code.is_empty() {
                return Err(CallError::Dispatch("invalid_error"));
            }
            return Err(CallError::Service(ServiceError { code: error.code, message: error.message }));
        }
        let result = service_decode(&reply.payload, decode_oa_chat_cancel_result).map_err(CallError::Refusal)?;
        Ok(result.value)
    }
}

