/// Administer the runtime's inference hosts, the gateway window and its local
/// keys, and read the inference audit. Each call is a rights decision for the
/// bound operator subject; same-account identity alone grants nothing. A
/// decision point that cannot answer reads unavailable.
pub trait Operator {
    type Error;
    /// Read the configured hosts, their router state and each hosted
    /// credential's spend today. Gated by abstraction.inference/host.manage on
    /// resource account.
    fn hosts(&self) -> Result<HostList, Self::Error>;
    /// Conditionally add one host. Gated by host.manage. For the bound operator
    /// program and the runtime's other operator programs it also writes the
    /// permit rule abstraction.inference/complete on host:<name>, and for a
    /// hosted host with a credential it writes the runtime's own permit rule
    /// abstraction.credentials/apply on credential:<name>, which the router's
    /// listing reads need. Existing rules are left as they are.
    fn add_host(&self, expected_revision: String, host: HostEntry) -> Result<HostChange, Self::Error>;
    /// Conditionally remove one host; operations already admitted run to their
    /// end. Gated by host.manage. Rules are left as they are.
    fn remove_host(&self, expected_revision: String, name: String) -> Result<HostChange, Self::Error>;
    /// Read the local keys of the receiving account. Gated by
    /// abstraction.inference/key.issue on resource account.
    fn keys(&self) -> Result<KeyList, Self::Error>;
    /// Mint a local key for program, an absolute executable path, and hold it
    /// in the platform store. credential, when not empty, names the hosted
    /// credential the window's requests for that program may spend under. Gated
    /// by key.issue. The key grants nothing: the window still binds the peer,
    /// requires that program, and decides abstraction.inference/complete and
    /// credentials apply for it.
    fn issue_key(&self, program: String, credential: String) -> Result<KeyIssued, Self::Error>;
    /// Destroy the active local key of program. Gated by key.issue.
    fn revoke_key(&self, program: String) -> Result<KeyRevoked, Self::Error>;
    /// Read retained inference decisions from both routes. Gated by
    /// abstraction.inference/audit.read on resource account. cursor 0 starts at
    /// the oldest retained entry; max_entries is 1..256.
    fn audit(&self, cursor: i64, max_entries: i64) -> Result<AuditPage, Self::Error>;
    /// Read the gateway window setting and whether the window listens now.
    /// Gated by abstraction.inference/host.manage on resource account.
    fn gateway(&self) -> Result<GatewayState, Self::Error>;
    /// Conditionally write the gateway window setting to the runtime state and
    /// apply it to the running runtime: open listens on address, and closed
    /// stops the listener and every window connection. address is
    /// 127.0.0.1:<port>; empty keeps the recorded address when opening, and
    /// 127.0.0.1:8793 when none is recorded. The setting survives a restart.
    /// Gated by host.manage.
    fn set_gateway(&self, expected_revision: String, open: bool, address: String) -> Result<GatewayChange, Self::Error>;
}

